changeSet.sql:
ALTER TABLE stop_factors.stop_factor
    ADD CONSTRAINT ck_stop_factor_version_number CHECK (version_number >= 1),
    ADD CONSTRAINT ck_stop_factor_root CHECK ((root_id IS NULL) = (version_number = 1)),
    ADD CONSTRAINT ck_stop_factor_validity CHECK (valid_to IS NULL OR valid_to >= valid_from),
    ADD CONSTRAINT ck_stop_factor_params_is_object CHECK (jsonb_typeof(params) = 'object');

CREATE UNIQUE INDEX ux_stop_factor_current_version
    ON stop_factors.stop_factor ((COALESCE(root_id, id)))
    WHERE valid_to IS NULL;

CREATE UNIQUE INDEX ux_stop_factor_version_number
    ON stop_factors.stop_factor ((COALESCE(root_id, id)), version_number);

CREATE INDEX idx_stop_factor_metric_id ON stop_factors.stop_factor (metric_id);

rollback.sql:
DROP INDEX stop_factors.idx_stop_factor_metric_id;
DROP INDEX stop_factors.ux_stop_factor_version_number;
DROP INDEX stop_factors.ux_stop_factor_current_version;
ALTER TABLE stop_factors.stop_factor
    DROP CONSTRAINT ck_stop_factor_params_is_object,
    DROP CONSTRAINT ck_stop_factor_validity,
    DROP CONSTRAINT ck_stop_factor_root,
    DROP CONSTRAINT ck_stop_factor_version_number;
